code.css:
h1{font-size:var(--ui-size-title);margin:0 0 var(--ui-space-3)}
.bar{display:flex;flex-wrap:wrap;gap:var(--ui-space-3);align-items:center;margin-bottom:var(--ui-space-2)}
label{display:flex;gap:var(--ui-space-2);align-items:center}
button{min-height:var(--ui-target);padding:0 var(--ui-space-4);border:1px solid var(--ui-control-border);border-radius:var(--ui-radius-control);background:var(--ui-surface);color:var(--ui-text);font:inherit;cursor:pointer}
button:focus-visible,input:focus-visible,canvas:focus-visible{outline:3px solid var(--ui-accent);outline-offset:2px}
input[type=color]{min-height:var(--ui-target);width:56px}
input[type=checkbox]{width:20px;height:20px}
#msg{color:var(--ui-text-secondary);font-size:var(--ui-size-secondary);margin:0 0 var(--ui-space-2);min-height:1.5em}
canvas{width:100%;max-width:800px;height:auto;aspect-ratio:8/5;background:#fff;border:1px solid var(--ui-control-border);border-radius:var(--ui-radius-control);touch-action:none;cursor:crosshair;display:block}

