const c=document.getElementById('board');const x=c.getContext('2d');
const msg=document.getElementById('msg');
x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);
x.lineCap='round';x.lineJoin='round';
let drawing=false,last=null,dirty=false;
function pos(e){const r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height};}
function style(){x.strokeStyle=document.getElementById('erase').checked?'#fff':document.getElementById('color').value;x.fillStyle=x.strokeStyle;x.lineWidth=Number(document.getElementById('size').value);}
c.addEventListener('pointerdown',e=>{drawing=true;c.setPointerCapture(e.pointerId);last=pos(e);style();x.beginPath();x.arc(last.x,last.y,x.lineWidth/2,0,Math.PI*2);x.fill();dirty=true;msg.textContent='';});
c.addEventListener('pointermove',e=>{if(!drawing)return;const p=pos(e);style();x.beginPath();x.moveTo(last.x,last.y);x.lineTo(p.x,p.y);x.stroke();last=p;});
function stop(){drawing=false;}
c.addEventListener('pointerup',stop);c.addEventListener('pointercancel',stop);
document.getElementById('clear').addEventListener('click',()=>{x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);msg.textContent=dirty?'Board cleared.':'The board is already empty.';dirty=false;});
msg.textContent='Press and drag on the board to draw. The drawing is not kept when you close this tool.';

